def factorial_rec(n: int) -> int:
    if n < 0:
        raise ValueError("n")
    if n <= 1:
        return 1
    return n * factorial_rec(n - 1)

def factorial(n: int) -> int:
    if n < 0:
        raise ValueError("n")
    ans = 1
    for i in range(2, n + 1):
        ans *= i
    return ans
